/**
 * Touch Handler Hooks
 *
 * React hooks for handling touch gestures in the canvas editor.
 * Provides hooks for drag, resize, rotate, and pinch-to-zoom gestures.
 *
 * @module UseTouchGestures
 */

import React, { useRef, useCallback, useEffect, useState } from 'react';
import { useCanvasStore } from '@/store/canvas-store';
import { CanvasElement, Transform, Point } from '@/types/canvas-elements';
import {
  TouchGesture,
  GestureEvent,
  GestureType,
  touchToCanvas,
  isTouchDevice,
  getTouchSupportLevel,
  TouchGestureConfig,
} from '@/canvas-editor/utils/touch-gestures';

/**
 * Use touch drag handler
 *
 * Handles drag gestures for canvas elements.
 *
 * Phase 3 Refactor: This hook now only handles gesture detection.
 * Element updates are handled by parent components via callbacks.
 */
export function useTouchDrag(
  element: CanvasElement,
  onDragStart?: () => void,
  onDragEnd?: (transform: Transform) => void,
  onTransform?: (transform: Transform) => void, // Phase 3: Added callback for real-time updates
  config?: TouchGestureConfig
) {
  const { selectElement } = useCanvasStore();
  const dragState = useRef<{
    isDragging: boolean;
    startPoint: Point;
    elementStart: Point;
  }>({
    isDragging: false,
    startPoint: { x: 0, y: 0 },
    elementStart: { x: 0, y: 0 },
  });

  const gestureRef = useRef<TouchGesture | null>(null);

  // Initialize gesture handler
  useEffect(() => {
    if (!isTouchDevice()) return;

    gestureRef.current = new TouchGesture(config);

    const gesture = gestureRef.current;

    gesture.on('drag', (event: GestureEvent) => {
      if (event.type === 'drag') {
        handleDragMove(event);
      }
    });

    return () => {
      if (gestureRef.current) {
        gestureRef.current.reset();
      }
    };
  }, [config]);

  const handleDragStart = useCallback(
    (e: React.TouchEvent, stage: any) => {
      if (!isTouchDevice()) return;

      const touch = e.touches[0];
      const canvasPoint = touchToCanvas(touch, stage);

      dragState.current = {
        isDragging: true,
        startPoint: canvasPoint,
        elementStart: { x: element.x, y: element.y },
      };

      onDragStart?.();
    },
    [element, onDragStart]
  );

  const handleDragMove = useCallback(
    (event: GestureEvent) => {
      if (!dragState.current.isDragging) return;

      const { startPoint, elementStart } = dragState.current;
      if (event.type === 'drag') {
        const deltaX = event.currentPoint.x - startPoint.x;
        const deltaY = event.currentPoint.y - startPoint.y;

        const newX = elementStart.x + deltaX;
        const newY = elementStart.y + deltaY;

        // Phase 3: Use callback instead of direct store update
        onTransform?.({
          x: newX,
          y: newY,
          width: element.width,
          height: element.height,
          rotation: element.rotation,
        });
      }
    },
    [element, onTransform]
  );

  const handleDragEnd = useCallback(
    (e: React.TouchEvent, stage: any) => {
      if (!dragState.current.isDragging) return;

      const touch = e.touches[0] || e.changedTouches[0];
      const canvasPoint = touchToCanvas(touch, stage);

      const transform: Transform = {
        x: canvasPoint.x,
        y: canvasPoint.y,
      };

      dragState.current.isDragging = false;

      onDragEnd?.(transform);
    },
    [onDragEnd]
  );

  const handleTouchStart = useCallback(
    (e: React.TouchEvent, stage: any) => {
      if (!gestureRef.current || e.touches.length !== 1) return;

      gestureRef.current.handleTouchStart(e.touches);
      handleDragStart(e, stage);
    },
    [handleDragStart]
  );

  const handleTouchMove = useCallback(
    (e: React.TouchEvent) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchMove(e.touches);
    },
    []
  );

  const handleTouchEnd = useCallback(
    (e: React.TouchEvent, stage: any) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchEnd(e.touches);
      handleDragEnd(e, stage);
    },
    [handleDragEnd]
  );

  return {
    onTouchStart: handleTouchStart,
    onTouchMove: handleTouchMove,
    onTouchEnd: handleTouchEnd,
    isDragging: dragState.current.isDragging,
  };
}

/**
 * Use touch resize handler
 *
 * Handles resize gestures for canvas elements.
 *
 * Phase 3 Refactor: This hook now only handles gesture detection.
 * Element updates are handled by parent components via callbacks.
 */
export function useTouchResize(
  element: CanvasElement,
  handle: 'top-left' | 'top-center' | 'top-right' | 'middle-left' | 'middle-right' | 'bottom-left' | 'bottom-center' | 'bottom-right',
  onResizeStart?: () => void,
  onResizeEnd?: (transform: Transform) => void,
  onTransform?: (transform: Transform) => void, // Phase 3: Added callback for real-time updates
  keepAspectRatio?: boolean,
  config?: TouchGestureConfig
) {
  const resizeState = useRef<{
    isResizing: boolean;
    startPoint: Point;
    elementStart: {
      x: number;
      y: number;
      width: number;
      height: number;
    };
  }>({
    isResizing: false,
    startPoint: { x: 0, y: 0 },
    elementStart: { x: 0, y: 0, width: 0, height: 0 },
  });

  const gestureRef = useRef<TouchGesture | null>(null);

  // Initialize gesture handler
  useEffect(() => {
    if (!isTouchDevice()) return;

    gestureRef.current = new TouchGesture(config);

    const gesture = gestureRef.current;

    gesture.on('drag', (event: GestureEvent) => {
      if (event.type === 'drag') {
        handleResizeMove(event);
      }
    });

    return () => {
      if (gestureRef.current) {
        gestureRef.current.reset();
      }
    };
  }, [config]);

  const handleResizeStart = useCallback(
    (e: React.TouchEvent, stage: any) => {
      if (!isTouchDevice()) return;

      const touch = e.touches[0];
      const canvasPoint = touchToCanvas(touch, stage);

      resizeState.current = {
        isResizing: true,
        startPoint: canvasPoint,
        elementStart: {
          x: element.x,
          y: element.y,
          width: element.width,
          height: element.height,
        },
      };

      onResizeStart?.();
    },
    [element, onResizeStart]
  );

  const handleResizeMove = useCallback(
    (event: GestureEvent) => {
      if (!resizeState.current.isResizing) return;

      const { startPoint, elementStart } = resizeState.current;
      if (event.type === 'drag') {
        const deltaX = event.currentPoint.x - startPoint.x;
        const deltaY = event.currentPoint.y - startPoint.y;

        let newX = elementStart.x;
        let newY = elementStart.y;
        let newWidth = elementStart.width;
        let newHeight = elementStart.height;

        // Apply resize based on handle
        switch (handle) {
          case 'top-left':
            newX = elementStart.x + deltaX;
            newY = elementStart.y + deltaY;
            newWidth = elementStart.width - deltaX;
            newHeight = elementStart.height - deltaY;
            break;
          case 'top-center':
            newY = elementStart.y + deltaY;
            newHeight = elementStart.height - deltaY;
            break;
          case 'top-right':
            newY = elementStart.y + deltaY;
            newWidth = elementStart.width + deltaX;
            newHeight = elementStart.height - deltaY;
            break;
          case 'middle-left':
            newX = elementStart.x + deltaX;
            newWidth = elementStart.width - deltaX;
            break;
          case 'middle-right':
            newWidth = elementStart.width + deltaX;
            break;
          case 'bottom-left':
            newX = elementStart.x + deltaX;
            newWidth = elementStart.width - deltaX;
            newHeight = elementStart.height + deltaY;
            break;
          case 'bottom-center':
            newHeight = elementStart.height + deltaY;
            break;
          case 'bottom-right':
            newWidth = elementStart.width + deltaX;
            newHeight = elementStart.height + deltaY;
            break;
        }

        // Maintain aspect ratio if enabled
        if (keepAspectRatio) {
          const aspectRatio = elementStart.width / elementStart.height;

          if (Math.abs(deltaX) > Math.abs(deltaY)) {
            newHeight = newWidth / aspectRatio;
          } else {
            newWidth = newHeight * aspectRatio;
          }
        }

        // Prevent negative dimensions
        newWidth = Math.max(20, newWidth);
        newHeight = Math.max(20, newHeight);

        // Phase 3: Use callback instead of direct store update
        onTransform?.({
          x: newX,
          y: newY,
          width: newWidth,
          height: newHeight,
          rotation: element.rotation,
        });
      }
    },
    [element, handle, keepAspectRatio, onTransform]
  );

  const handleResizeEnd = useCallback(
    (e: React.TouchEvent, stage: any) => {
      if (!resizeState.current.isResizing) return;

      const touch = e.touches[0] || e.changedTouches[0];
      const canvasPoint = touchToCanvas(touch, stage);

      const transform: Transform = {
        x: canvasPoint.x,
        y: canvasPoint.y,
        width: element.width,
        height: element.height,
      };

      resizeState.current.isResizing = false;

      onResizeEnd?.(transform);
    },
    [element, onResizeEnd]
  );

  const handleTouchStart = useCallback(
    (e: React.TouchEvent, stage: any) => {
      if (!gestureRef.current || e.touches.length !== 1) return;

      gestureRef.current.handleTouchStart(e.touches);
      handleResizeStart(e, stage);
    },
    [handleResizeStart]
  );

  const handleTouchMove = useCallback(
    (e: React.TouchEvent) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchMove(e.touches);
    },
    []
  );

  const handleTouchEnd = useCallback(
    (e: React.TouchEvent, stage: any) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchEnd(e.touches);
      handleResizeEnd(e, stage);
    },
    [handleResizeEnd]
  );

  return {
    onTouchStart: handleTouchStart,
    onTouchMove: handleTouchMove,
    onTouchEnd: handleTouchEnd,
    isResizing: resizeState.current.isResizing,
  };
}

/**
 * Use touch rotate handler
 *
 * Handles rotation gestures for canvas elements.
 *
 * Phase 3 Refactor: This hook now only handles gesture detection.
 * Element updates are handled by parent components via callbacks.
 */
export function useTouchRotate(
  element: CanvasElement,
  onRotateStart?: () => void,
  onRotateEnd?: (rotation: number) => void,
  onTransform?: (transform: Transform) => void, // Phase 3: Added callback for real-time updates
  config?: TouchGestureConfig
) {
  const rotateState = useRef<{
    isRotating: boolean;
    startAngle: number;
    elementRotation: number;
  }>({
    isRotating: false,
    startAngle: 0,
    elementRotation: 0,
  });

  const gestureRef = useRef<TouchGesture | null>(null);

  // Initialize gesture handler
  useEffect(() => {
    if (!isTouchDevice()) return;

    gestureRef.current = new TouchGesture(config);

    const gesture = gestureRef.current;

    gesture.on('rotate', (event: GestureEvent) => {
      if (event.type === 'rotate') {
        handleRotateMove(event);
      }
    });

    return () => {
      if (gestureRef.current) {
        gestureRef.current.reset();
      }
    };
  }, [config]);

  const handleRotateStart = useCallback(
    (e: React.TouchEvent, stage: any) => {
      if (!isTouchDevice() || e.touches.length !== 2) return;

      const touch1 = e.touches[0];
      const touch2 = e.touches[1];

      const canvasPoint1 = touchToCanvas(touch1, stage);
      const canvasPoint2 = touchToCanvas(touch2, stage);

      const dx = canvasPoint2.x - canvasPoint1.x;
      const dy = canvasPoint2.y - canvasPoint1.y;
      const angle = (Math.atan2(dy, dx) * 180) / Math.PI;

      rotateState.current = {
        isRotating: true,
        startAngle: angle,
        elementRotation: element.rotation,
      };

      onRotateStart?.();
    },
    [element.rotation, onRotateStart]
  );

  const handleRotateMove = useCallback(
    (event: GestureEvent) => {
      if (!rotateState.current.isRotating) return;

      const { startAngle, elementRotation } = rotateState.current;
      if (event.type === 'rotate') {
        const deltaAngle = event.deltaAngle;
        const newRotation = elementRotation + deltaAngle;

        // Phase 3: Use callback instead of direct store update
        onTransform?.({
          x: element.x,
          y: element.y,
          width: element.width,
          height: element.height,
          rotation: newRotation,
        });
      }
    },
    [element, onTransform]
  );

  const handleRotateEnd = useCallback(
    (e: React.TouchEvent) => {
      if (!rotateState.current.isRotating) return;

      const currentRotation = element.rotation;
      rotateState.current.isRotating = false;

      onRotateEnd?.(currentRotation);
    },
    [element.rotation, onRotateEnd]
  );

  const handleTouchStart = useCallback(
    (e: React.TouchEvent, stage: any) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchStart(e.touches);

      if (e.touches.length === 2) {
        handleRotateStart(e, stage);
      }
    },
    [handleRotateStart]
  );

  const handleTouchMove = useCallback(
    (e: React.TouchEvent) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchMove(e.touches);
    },
    []
  );

  const handleTouchEnd = useCallback(
    (e: React.TouchEvent) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchEnd(e.touches);

      if (e.touches.length === 0) {
        handleRotateEnd(e);
      }
    },
    [handleRotateEnd]
  );

  return {
    onTouchStart: handleTouchStart,
    onTouchMove: handleTouchMove,
    onTouchEnd: handleTouchEnd,
    isRotating: rotateState.current.isRotating,
  };
}

/**
 * Use pinch to zoom handler
 *
 * Handles pinch-to-zoom gestures for the canvas stage.
 */
export function usePinchToZoom(
  stage: any,
  onZoomChange?: (zoom: number) => void,
  config?: TouchGestureConfig
) {
  const { setZoom, setPan } = useCanvasStore();
  const zoomState = useRef<{
    isZooming: boolean;
    initialZoom: number;
    initialScale: number;
    center: Point;
  }>({
    isZooming: false,
    initialZoom: 1,
    initialScale: 1,
    center: { x: 0, y: 0 },
  });

  const gestureRef = useRef<TouchGesture | null>(null);

  // Initialize gesture handler
  useEffect(() => {
    if (!isTouchDevice() || !stage) return;

    gestureRef.current = new TouchGesture(config);

    const gesture = gestureRef.current;

    gesture.on('pinch', (event: GestureEvent) => {
      if (event.type === 'pinch') {
        handlePinchMove(event);
      }
    });

    return () => {
      if (gestureRef.current) {
        gestureRef.current.reset();
      }
    };
  }, [config, stage]);

  const handlePinchStart = useCallback(
    (e: React.TouchEvent) => {
      if (!isTouchDevice() || !stage || e.touches.length !== 2) return;

      const touch1 = e.touches[0];
      const touch2 = e.touches[1];

      const center = {
        x: (touch1.clientX + touch2.clientX) / 2,
        y: (touch1.clientY + touch2.clientY) / 2,
      };

      zoomState.current = {
        isZooming: true,
        initialZoom: stage.scaleX(),
        initialScale: 1,
        center,
      };
    },
    [stage]
  );

  const handlePinchMove = useCallback(
    (event: GestureEvent) => {
      if (!zoomState.current.isZooming || !stage) return;

      if (event.type === 'pinch') {
        const { initialZoom, center } = zoomState.current;
        const newScale = initialZoom * event.scale;

        // Limit zoom
        const clampedScale = Math.max(0.1, Math.min(5, newScale));

        // Calculate new position
        const mousePointTo = {
          x: (center.x - stage.x()) / initialZoom,
          y: (center.y - stage.y()) / initialZoom,
        };

        const newPos = {
          x: center.x - mousePointTo.x * clampedScale,
          y: center.y - mousePointTo.y * clampedScale,
        };

        stage.scale({ x: clampedScale, y: clampedScale });
        stage.position(newPos);
        stage.batchDraw();

        setZoom(clampedScale);
        setPan(newPos);

        onZoomChange?.(clampedScale);
      }
    },
    [stage, setZoom, setPan, onZoomChange]
  );

  const handlePinchEnd = useCallback(
    (e: React.TouchEvent) => {
      if (!zoomState.current.isZooming) return;

      zoomState.current.isZooming = false;
    },
    []
  );

  const handleTouchStart = useCallback(
    (e: React.TouchEvent) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchStart(e.touches);

      if (e.touches.length === 2) {
        handlePinchStart(e);
      }
    },
    [handlePinchStart]
  );

  const handleTouchMove = useCallback(
    (e: React.TouchEvent) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchMove(e.touches);
    },
    []
  );

  const handleTouchEnd = useCallback(
    (e: React.TouchEvent) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchEnd(e.touches);

      if (e.touches.length === 0) {
        handlePinchEnd(e);
      }
    },
    [handlePinchEnd]
  );

  return {
    onTouchStart: handleTouchStart,
    onTouchMove: handleTouchMove,
    onTouchEnd: handleTouchEnd,
    isZooming: zoomState.current.isZooming,
  };
}

/**
 * Use touch gestures hook
 *
 * Combined hook for all touch gestures.
 */
export function useTouchGestures(
  stage: any,
  onGesture?: (gesture: GestureEvent) => void,
  config?: TouchGestureConfig
) {
  const gestureRef = useRef<TouchGesture | null>(null);

  // Initialize gesture handler
  useEffect(() => {
    if (!isTouchDevice()) return;

    gestureRef.current = new TouchGesture(config);

    const gesture = gestureRef.current;

    // Register all gesture callbacks
    const gestureTypes: GestureType[] = [
      'tap',
      'double-tap',
      'long-press',
      'drag',
      'pinch',
      'rotate',
      'swipe',
    ];

    gestureTypes.forEach(type => {
      gesture.on(type, (event: GestureEvent) => {
        onGesture?.(event);
      });
    });

    return () => {
      if (gestureRef.current) {
        gestureRef.current.reset();
      }
    };
  }, [config, onGesture]);

  const handleTouchStart = useCallback(
    (e: React.TouchEvent) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchStart(e.touches);
    },
    []
  );

  const handleTouchMove = useCallback(
    (e: React.TouchEvent) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchMove(e.touches);
    },
    []
  );

  const handleTouchEnd = useCallback(
    (e: React.TouchEvent) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchEnd(e.touches);
    },
    []
  );

  const handleTouchCancel = useCallback(
    (e: React.TouchEvent) => {
      if (!gestureRef.current) return;

      gestureRef.current.handleTouchCancel();
    },
    []
  );

  return {
    onTouchStart: handleTouchStart,
    onTouchMove: handleTouchMove,
    onTouchEnd: handleTouchEnd,
    onTouchCancel: handleTouchCancel,
    isGestureActive: gestureRef.current?.isGestureActive() ?? false,
    currentGestureType: gestureRef.current?.getCurrentGestureType() ?? 'none',
  };
}

/**
 * Use touch device detection hook
 *
 * Detects if the current device supports touch.
 */
export function useTouchDevice() {
  const [isTouchSupported, setIsTouchSupported] = React.useState(false);
  const [touchSupportLevel, setTouchSupportLevel] = React.useState<'none' | 'basic' | 'multi'>('none');

  useEffect(() => {
    setIsTouchSupported(isTouchDevice());
    setTouchSupportLevel(getTouchSupportLevel());
  }, []);

  return {
    isTouchSupported,
    touchSupportLevel,
  };
}