'use client';

import React, { useState, useCallback, useMemo } from 'react';
import { Image as KonvaImage, Rect, Group } from 'react-konva';
import useImage from 'use-image';
import { BaseElement } from './BaseElement';
import { CanvasElement, ImageElementData } from '@/types/canvas-elements';

interface ImageElementProps {
  element: CanvasElement;
  isSelected: boolean;
  onSelect: (id: string) => void;
  onTransform: (transform: any) => void;
  onElementUpdate?: (elementId: string, updates: Partial<CanvasElement>) => void; // ✅ ADD - Callback for updates
  enableResize?: boolean;
  enableRotate?: boolean;
  keepAspectRatio?: boolean;
}

/**
 * ImageElement - Renders images in the canvas editor
 *
 * Features:
 * - Image loading with use-image hook
 * - Object-fit modes: cover, contain, fill, none, scale-down
 * - Loading state with spinner
 * - Error handling with fallback
 * - Image filters: blur, grayscale, sepia, saturate, brightness, contrast, hueRotate, invert
 * - Border radius support
 * - Border support
 * - Shadow support
 * - Blend mode support
 */
export const ImageElement: React.FC<ImageElementProps> = ({
  element,
  isSelected,
  onSelect,
  onTransform,
  enableResize = true,
  enableRotate = true,
  keepAspectRatio = false,
}) => {
  const imageData = element.data as ImageElementData;

  // Load image with use-image hook
  const [image, imageStatus] = useImage(imageData.url, 'anonymous');

  // Calculate image dimensions based on object-fit
  const imageDimensions = useMemo(() => {
    if (!image) {
      return { width: 0, height: 0, x: 0, y: 0 };
    }

    const imgWidth = image.width;
    const imgHeight = image.height;
    const containerWidth = element.width;
    const containerHeight = element.height;

    let width = imgWidth;
    let height = imgHeight;
    let x = 0;
    let y = 0;

    switch (imageData.objectFit) {
      case 'cover':
        // Scale image to cover the entire container
        const coverRatio = Math.max(containerWidth / imgWidth, containerHeight / imgHeight);
        width = imgWidth * coverRatio;
        height = imgHeight * coverRatio;
        x = (containerWidth - width) / 2;
        y = (containerHeight - height) / 2;
        break;

      case 'contain':
        // Scale image to fit within the container
        const containRatio = Math.min(containerWidth / imgWidth, containerHeight / imgHeight);
        width = imgWidth * containRatio;
        height = imgHeight * containRatio;
        x = (containerWidth - width) / 2;
        y = (containerHeight - height) / 2;
        break;

      case 'fill':
        // Stretch image to fill the container
        width = containerWidth;
        height = containerHeight;
        x = 0;
        y = 0;
        break;

      case 'scale-down':
        // Scale image down if it's larger than container, otherwise use none
        const scaleDownRatio = Math.min(containerWidth / imgWidth, containerHeight / imgHeight);
        if (scaleDownRatio < 1) {
          width = imgWidth * scaleDownRatio;
          height = imgHeight * scaleDownRatio;
          x = (containerWidth - width) / 2;
          y = (containerHeight - height) / 2;
        } else {
          width = imgWidth;
          height = imgHeight;
          x = (containerWidth - width) / 2;
          y = (containerHeight - height) / 2;
        }
        break;

      case 'none':
      default:
        // Use original image size, centered
        width = imgWidth;
        height = imgHeight;
        x = (containerWidth - width) / 2;
        y = (containerHeight - height) / 2;
        break;
    }

    return { width, height, x, y };
  }, [image, element.width, element.height, imageData.objectFit]);

  // Build filter array from image data
  const filters = useMemo(() => {
    const filterArray: any[] = [];

    if (imageData.filters.blur && imageData.filters.blur > 0) {
      filterArray.push({
        name: 'Blur',
        value: imageData.filters.blur,
      });
    }

    if (imageData.filters.grayscale && imageData.filters.grayscale > 0) {
      filterArray.push({
        name: 'Grayscale',
        value: imageData.filters.grayscale,
      });
    }

    if (imageData.filters.sepia && imageData.filters.sepia > 0) {
      filterArray.push({
        name: 'Sepia',
        value: imageData.filters.sepia,
      });
    }

    if (imageData.filters.saturate && imageData.filters.saturate !== 100) {
      filterArray.push({
        name: 'Saturate',
        value: imageData.filters.saturate,
      });
    }

    if (imageData.filters.brightness && imageData.filters.brightness !== 0) {
      filterArray.push({
        name: 'Brightness',
        value: imageData.filters.brightness,
      });
    }

    if (imageData.filters.contrast && imageData.filters.contrast !== 0) {
      filterArray.push({
        name: 'Contrast',
        value: imageData.filters.contrast,
      });
    }

    if (imageData.filters.hueRotate && imageData.filters.hueRotate !== 0) {
      filterArray.push({
        name: 'HueRotate',
        value: imageData.filters.hueRotate,
      });
    }

    if (imageData.filters.invert && imageData.filters.invert > 0) {
      filterArray.push({
        name: 'Invert',
        value: imageData.filters.invert,
      });
    }

    return filterArray;
  }, [imageData.filters]);

  // Clip function for border radius
  const clipFunc = useCallback((ctx: any) => {
    if (imageData.borderRadius && imageData.borderRadius > 0) {
      const { width, height } = element;
      const radius = Math.min(imageData.borderRadius, Math.min(width, height) / 2);

      ctx.beginPath();
      ctx.moveTo(radius, 0);
      ctx.lineTo(width - radius, 0);
      ctx.quadraticCurveTo(width, 0, width, radius);
      ctx.lineTo(width, height - radius);
      ctx.quadraticCurveTo(width, height, width - radius, height);
      ctx.lineTo(radius, height);
      ctx.quadraticCurveTo(0, height, 0, height - radius);
      ctx.lineTo(0, radius);
      ctx.quadraticCurveTo(0, 0, radius, 0);
      ctx.closePath();
    }
  }, [element.width, element.height, imageData.borderRadius]);

  // Render loading state
  const renderLoading = () => (
    <Group>
      {/* Background */}
      <Rect
        x={0}
        y={0}
        width={element.width}
        height={element.height}
        fill="#1a1a2e"
        cornerRadius={imageData.borderRadius || 0}
      />

      {/* Loading indicator */}
      <Group x={element.width / 2} y={element.height / 2}>
        {/* Spinning circle */}
        <Rect
          x={-20}
          y={-20}
          width={40}
          height={40}
          stroke="#00E5FF"
          strokeWidth={3}
          cornerRadius={20}
          opacity={0.5}
        />
        <Rect
          x={-20}
          y={-20}
          width={40}
          height={40}
          stroke="#00E5FF"
          strokeWidth={3}
          cornerRadius={20}
          rotation={45}
          opacity={0.7}
        />
      </Group>

      {/* Loading text */}
      <Rect
        x={0}
        y={element.height / 2 + 30}
        width={element.width}
        height={24}
        fill="transparent"
      />
    </Group>
  );

  // Render error state
  const renderError = () => (
    <Group>
      {/* Background */}
      <Rect
        x={0}
        y={0}
        width={element.width}
        height={element.height}
        fill="#1a1a2e"
        cornerRadius={imageData.borderRadius || 0}
      />

      {/* Error icon */}
      <Group x={element.width / 2} y={element.height / 2}>
        {/* X icon */}
        <Rect
          x={-15}
          y={-2}
          width={30}
          height={4}
          fill="#ff4444"
          rotation={45}
        />
        <Rect
          x={-15}
          y={-2}
          width={30}
          height={4}
          fill="#ff4444"
          rotation={-45}
        />
      </Group>
    </Group>
  );

  // Render border
  const renderBorder = () => {
    if (!imageData.borderWidth || imageData.borderWidth <= 0) {
      return null;
    }

    return (
      <Rect
        x={0}
        y={0}
        width={element.width}
        height={element.height}
        stroke={imageData.borderColor || '#ffffff'}
        strokeWidth={imageData.borderWidth}
        cornerRadius={imageData.borderRadius || 0}
        fillEnabled={false}
      />
    );
  };

  // Render shadow
  const renderShadow = () => {
    if (!imageData.shadow) {
      return null;
    }

    return (
      <Rect
        x={0}
        y={0}
        width={element.width}
        height={element.height}
        fill="black"
        opacity={0.3}
        cornerRadius={imageData.borderRadius || 0}
        offsetX={5}
        offsetY={5}
      />
    );
  };

  // Determine which content to render
  const renderContent = () => {
    if (imageStatus === 'loading') {
      return renderLoading();
    }

    if (imageStatus === 'failed') {
      return renderError();
    }

    if (!image) {
      return renderError();
    }

    return (
      <KonvaImage
        image={image}
        x={imageDimensions.x}
        y={imageDimensions.y}
        width={imageDimensions.width}
        height={imageDimensions.height}
        filters={filters.map(f => f.name)}
        blur={imageData.filters.blur || 0}
        grayscale={imageData.filters.grayscale || 0}
        sepia={imageData.filters.sepia || 0}
        saturate={imageData.filters.saturate || 100}
        brightness={imageData.filters.brightness || 0}
        contrast={imageData.filters.contrast || 0}
        hueRotate={imageData.filters.hueRotate || 0}
        invert={imageData.filters.invert || 0}
        opacity={element.opacity}
        globalCompositeOperation={imageData.blendMode || 'source-over'}
        clipFunc={imageData.borderRadius && imageData.borderRadius > 0 ? clipFunc : undefined}
        perfectDrawEnabled={false}
      />
    );
  };

  return (
    <BaseElement
      element={element}
      isSelected={isSelected}
      onSelect={onSelect}
      onTransform={onTransform}
      enableResize={enableResize}
      enableRotate={enableRotate}
      keepAspectRatio={keepAspectRatio}
    >
      <Group>
        {/* Render shadow if enabled */}
        {renderShadow()}

        {/* Render main content */}
        <Group clipFunc={imageData.borderRadius && imageData.borderRadius > 0 ? clipFunc : undefined}>
          {renderContent()}
        </Group>

        {/* Render border if enabled */}
        {renderBorder()}
      </Group>
    </BaseElement>
  );
};