'use client';

import React from 'react';
import { Group, Rect, Text, Line, Circle, Star } from 'react-konva';
import useImage from 'use-image';
import { BaseElement } from './BaseElement';
import { CanvasElement, DecoratorElementData, DecoratorType, DecoratorConfig } from '@/types/canvas-elements';
import { CornerAccent } from '@/types/decorators';

// Default fallback config for decorators
const DEFAULT_FALLBACK_CONFIG: DecoratorConfig = {
  slideNumber: { enabled: false, position: 'bottom-right', size: 48, color: '#666666' },
  border: { enabled: false, width: 2, color: '#666666', style: 'solid' },
  hashtag: { enabled: false, text: undefined, position: 'top-left', size: 32, color: '#00E5FF' },
  watermark: { enabled: false, text: undefined, opacity: 0.3, position: 'center' },
  logo: { enabled: false, url: undefined, size: 80, position: 'top-right' },
  frame: { enabled: false, style: 'minimal', color: '#666666' },
  cornerAccents: { enabled: false },
  accentLines: { enabled: false, position: 'top', color: '#00E5FF', width: 4, offset: 40, thickness: 4, length: 80, gradient: false },
  pillarLabel: { enabled: false, position: 'bottom-right', size: 32 },
  backgroundEffects: { shadow: false, glow: false, blur: false, noise: false },
};

// Constants
const SLIDE_WIDTH = 1080;
const SLIDE_HEIGHT = 1350;

interface DecoratorElementProps {
  element: CanvasElement;
  isSelected: boolean;
  onSelect: (id: string) => void;
  onTransform: (transform: any) => void;
  enableResize?: boolean;
  enableRotate?: boolean;
  keepAspectRatio?: boolean;
  isEditing?: boolean; // New: Show visual feedback when editing decorator
  highlightColor?: string; // New: Custom highlight color
}

/**
 * DecoratorElement - Renders decorators in the canvas editor
 *
 * Features:
 * - Slide numbers (decimal, roman, circle, square, minimal, pillar-branded)
 * - Borders (solid, dashed, dotted, double, gradient)
 * - Corner accents (bracket, line, dot, triangle, circle, cross, star, diamond, arrow, wave)
 * - Frame styles (photo, film, tech, minimal, none)
 * - Logo with blend modes
 * - Hashtags
 * - Watermarks with positioning
 * - Accent lines (top, bottom, left, right)
 * - Pillar labels
 * - Background effects (shadow, glow, blur, noise)
 */
export const DecoratorElement: React.FC<DecoratorElementProps> = ({
  element,
  isSelected,
  onSelect,
  onTransform,
  enableResize = true,
  enableRotate = true,
  keepAspectRatio = false,
  isEditing = false,
  highlightColor = '#00E5FF',
}) => {
  const decoData = element.data as DecoratorElementData;

  // Use fallback config if config is undefined
  const config = decoData.config || DEFAULT_FALLBACK_CONFIG;

  // Log warning if using fallback config
  if (!decoData.config) {
    console.warn('[DecoratorElement] Using fallback config for element:', element.id);
  }

  // Visual feedback when editing
  const editingGlow = isEditing ? (
    <Rect
      x={0}
      y={0}
      width={element.width}
      height={element.height}
      fill={highlightColor}
      opacity={0.1}
      listening={false}
    />
  ) : null;

  const editingPulse = isEditing ? (
    <Rect
      x={0}
      y={0}
      width={element.width}
      height={element.height}
      stroke={highlightColor}
      strokeWidth={4}
      strokeDash={[10, 10]}
      opacity={0.6}
      listening={false}
    />
  ) : null;

/**
   * Render slide number
   */
  const renderSlideNumber = () => {
    if (!decoData.config || !decoData.config.slideNumber) return null;
    const config = decoData.config.slideNumber;
    if (!config.enabled) return null;

    const position = config.position;
    const size = config.size || 48;
    const color = config.color || '#666666';

    // Calculate position based on position type
    let x = 0;
    let y = 0;
    let text = '1';

    switch (position) {
      case 'top-left':
        x = 60;
        y = 60;
        break;
      case 'top-right':
        x = SLIDE_WIDTH - 60 - size * 2;
        y = 60;
        break;
      case 'bottom-left':
        x = 60;
        y = SLIDE_HEIGHT - 60 - size * 2;
        break;
      case 'bottom-right':
        x = SLIDE_WIDTH - 60 - size * 2;
        y = SLIDE_HEIGHT - 60 - size * 2;
        break;
      default:
        x = SLIDE_WIDTH - 60 - size * 2;
        y = SLIDE_HEIGHT - 60 - size * 2;
    }

    // Format number - simple decimal format
    let formattedNumber = text;

    return (
      <Group>
        <Text
          x={x}
          y={y}
          width={size * 2}
          height={size * 2}
          text={formattedNumber}
          fontSize={size}
          fontFamily="Inter"
          fontWeight="600"
          fontStyle="italic"
          fill={color}
          align="center"
          verticalAlign="middle"
          opacity={1}
        />
      </Group>
    );
  };

  /**
   * Render border
   */
  const renderBorder = () => {
    if (!decoData.config || !decoData.config.border) return null;
    const config = decoData.config.border;
    if (!config.enabled) return null;

    const { style, width, color } = config;
    const borderColor = color || '#666666';

    const borderStyle = style;
    const borderWidth = width || 2;

    return (
      <Rect
        x={0}
        y={0}
        width={SLIDE_WIDTH}
        height={SLIDE_HEIGHT}
        stroke={borderColor}
        strokeWidth={borderWidth}
        strokeDash={
          borderStyle === 'dashed' ? [8, 8] :
          borderStyle === 'dotted' ? [2, 4] :
          []
        }
        opacity={1}
        perfectDrawEnabled={false}
      />
    );
  };

  /**
   * Render corner accent
   */
  const renderCornerAccent = (corner: 'topLeft' | 'topRight' | 'bottomLeft' | 'bottomRight') => {
    if (!config || !config.cornerAccents) return null;
    const cornerAccents = config.cornerAccents;
    if (!cornerAccents) return null;

    const accent = cornerAccents[corner];
    if (!accent) return null;

    const style = accent.style as CornerAccent['style'];
    const size = accent.size || 48;
    const color = accent.color || '#00E5FF';
    const thickness = accent.thickness || 8;
    const rotation = accent.rotation || 0;
    const offset = accent.offset || { x: 0, y: 0 };
    const secondaryColor = accent.secondaryColor;

    const cornerPositions = {
      topLeft: { x: 0, y: 0 },
      topRight: { x: SLIDE_WIDTH, y: 0 },
      bottomLeft: { x: 0, y: SLIDE_HEIGHT },
      bottomRight: { x: SLIDE_WIDTH, y: SLIDE_HEIGHT },
    };

    const pos = cornerPositions[corner];
    const x = pos.x + offset.x;
    const y = pos.y + offset.y;

    switch (style) {
      case 'bracket':
        // Draw bracket corner
        return (
          <Group x={x} y={y} rotation={rotation}>
            {/* Top line */}
            <Line
              x={0}
              y={0}
              width={size}
              height={thickness}
              stroke={color}
              strokeWidth={thickness}
              lineCap="round"
              opacity={1}
            />
            {/* Side line */}
            <Line
              x={0}
              y={0}
              width={thickness}
              height={size}
              stroke={color}
              strokeWidth={thickness}
              lineCap="round"
              opacity={1}
            />
          </Group>
        );

      case 'line':
        // Simple line accent
        return (
          <Line
            x={x}
            y={y}
            width={size}
            height={size}
            stroke={color}
            strokeWidth={thickness}
            lineCap="round"
            opacity={1}
          />
        );

      case 'dot':
        // Circle dot
        return (
          <Circle
            x={x}
            y={y}
            radius={size / 2}
            fill={color}
            opacity={1}
          />
        );

      case 'triangle':
        // Triangle
        const h = size * Math.sqrt(3) / 2;
        const halfSize = size / 2;
        return (
          <Line
            points={[
              x, y - h / 2,
              x - halfSize, y + h / 2,
              x + halfSize, y + h / 2,
            ]}
            closed
            fill={color}
            stroke={color}
            strokeWidth={2}
            opacity={1}
          />
        );

      case 'circle':
        // Circle
        return (
          <Circle
            x={x}
            y={y}
            radius={size / 2}
            stroke={color}
            strokeWidth={2}
            opacity={1}
          />
        );

      case 'cross':
        // Cross
        return (
          <Group>
            <Line
              x={x - size / 2}
              y={y - size / 2}
              width={size}
              height={size}
              stroke={color}
              strokeWidth={thickness}
              opacity={1}
            />
            <Line
              x={x - size / 2}
              y={y - size / 2}
              width={size}
              height={size}
              stroke={color}
              strokeWidth={thickness}
              opacity={1}
            />
          </Group>
        );

      case 'star':
        // Star
        return (
          <Star
            x={x}
            y={y}
            numPoints={5}
            innerRadius={size / 4}
            outerRadius={size / 2}
            fill={color}
            stroke={color}
            strokeWidth={2}
            opacity={1}
          />
        );

      case 'diamond':
        // Diamond
        const diamondH = size * 0.7;
        const halfW = size / 2;
        return (
          <Line
            points={[
              x, y - diamondH / 2,
              x + halfW, y,
              x, y + diamondH / 2,
              x - halfW, y,
            ]}
            closed
            fill={color}
            stroke={color}
            strokeWidth={2}
            opacity={1}
          />
        );

      case 'arrow':
        // Arrow
        const arrowH = size * 0.7;
        const arrowHalfW = size / 6;
        return (
          <Group>
            <Line
              x={x}
              y={y - arrowH / 2}
              width={size}
              height={arrowH}
              stroke={color}
              strokeWidth={thickness}
              opacity={1}
            />
            <Line
              x={x + size}
              y={y}
              width={arrowHalfW}
              height={arrowHalfW}
              stroke={color}
              strokeWidth={thickness}
              opacity={1}
            />
          </Group>
        );

      case 'wave':
        // Wave
        return (
          <Line
            x={x}
            y={y}
            width={size}
            height={size * 0.3}
            stroke={color}
            strokeWidth={thickness}
            opacity={1}
          />
        );

      default:
        return null;
    }
  };

  /**
   * Render accent line
   */
  const renderAccentLine = (position: 'top' | 'bottom' | 'left' | 'right') => {
    if (!decoData.config || !decoData.config.accentLines) return null;
    const accentLines = decoData.config.accentLines;
    if (!accentLines || !accentLines.enabled) return null;

    const { offset, thickness, length, color, gradient } = accentLines;
    const accentColor = color || '#00E5FF';

    const positions = {
      top: { x: 0, y: offset || 40 },
      bottom: { x: 0, y: SLIDE_HEIGHT - (offset || 40) },
      left: { x: offset || 40, y: 0 },
      right: { x: SLIDE_WIDTH - (offset || 40), y: 0 },
    };

    const pos = positions[position];

    return (
      <Line
        x={pos.x}
        y={pos.y}
        width={position === 'top' || position === 'bottom' ? SLIDE_WIDTH : length || 80}
        height={position === 'left' || position === 'right' ? SLIDE_HEIGHT : length || 80}
        stroke={accentColor}
        strokeWidth={thickness}
        opacity={1}
        dash={gradient ? [4, 4] : undefined}
      />
    );
  };

  /**
   * Render watermark
   */
  const renderWatermark = () => {
    if (!decoData.config || !decoData.config.watermark) return null;
    const config = decoData.config.watermark;
    if (!config.enabled || !config.text) return null;

    const size = 120;
    const opacity = config.opacity ?? 0.3;

    return (
      <Group
        x={SLIDE_WIDTH / 2}
        y={SLIDE_HEIGHT / 2}
        offsetX={size}
        offsetY={size}
        rotation={-45}
        opacity={opacity}
      >
        <Text
          width={size * 2}
          height={size * 2}
          text={config.text}
          fontSize={size * 0.4}
          fontFamily="Arial"
          fill="#ffffff"
          align="center"
          verticalAlign="middle"
        />
      </Group>
    );
  };

  /**
   * Render logo
   */
  const renderLogo = () => {
    if (!decoData.config || !decoData.config.logo) return null;
    const config = decoData.config.logo;
    if (!config.enabled || !config.url) return null;

    const position = config.position;
    const size = config.size || 80;

    let x = 0;
    let y = 0;

    switch (position) {
      case 'top-left':
        x = 60;
        y = 60;
        break;
      case 'top-right':
        x = SLIDE_WIDTH - 60;
        y = 60;
        break;
      case 'bottom-left':
        x = 60;
        y = SLIDE_HEIGHT - 60;
        break;
      case 'bottom-right':
        x = SLIDE_WIDTH - 60;
        y = SLIDE_HEIGHT - 60;
        break;
      default:
        x = SLIDE_WIDTH - 60;
        y = SLIDE_HEIGHT - 60;
    }

    // Use-image hook for logo
    const [image] = useImage(config.url, 'anonymous');

    if (!image) {
      return null;
    }

    return (
      <Group
        x={x}
        y={y}
        width={size}
        height={size}
        offsetX={size / 2}
        offsetY={size / 2}
        opacity={1}
      >
        <Rect
          width={size}
          height={size}
          fillPatternImage={image}
        />
      </Group>
    );
  };

  /**
   * Render hashtag
   */
  const renderHashtag = () => {
    if (!decoData.config || !decoData.config.hashtag) return null;
    const config = decoData.config.hashtag;
    if (!config.enabled || !config.text) return null;

    const position = config.position;
    const size = config.size || 32;
    const color = config.color || '#00E5FF';

    let x = 0;
    let y = 0;

    switch (position) {
      case 'top-left':
        x = 60;
        y = 60;
        break;
      case 'top-right':
        x = SLIDE_WIDTH - 60;
        y = 60;
        break;
      case 'bottom-left':
        x = 60;
        y = SLIDE_HEIGHT - 60;
        break;
      case 'bottom-right':
        x = SLIDE_WIDTH - 60;
        y = SLIDE_HEIGHT - 60;
        break;
      default:
        x = 60;
        y = 60;
    }

    return (
      <Group>
        <Text
          x={x}
          y={y}
          text={`#${config.text}`}
          fontSize={size}
          fontFamily="Arial"
          fontWeight="600"
          fill={color}
          align="center"
          verticalAlign="middle"
        />
      </Group>
    );
  };

  /**
   * Render pillar label
   */
  const renderPillarLabel = () => {
    if (!decoData.config || !decoData.config.pillarLabel) return null;
    const config = decoData.config.pillarLabel;
    if (!config || !config.enabled) return null;

    const position = config.position;
    const size = config.size || 32;
    const color = '#00E5FF';

    let x = 0;
    let y = 0;

    switch (position) {
      case 'top-left':
        x = 60;
        y = 60;
        break;
      case 'top-right':
        x = SLIDE_WIDTH - 60;
        y = 60;
        break;
      case 'bottom-left':
        x = 60;
        y = SLIDE_HEIGHT - 60;
        break;
      case 'bottom-right':
        x = SLIDE_WIDTH - 60;
        y = SLIDE_HEIGHT - 60;
        break;
      default:
        x = SLIDE_WIDTH - 60;
        y = SLIDE_HEIGHT - 60;
    }

    return (
      <Group>
        <Text
          x={x}
          y={y}
          text="Pillar"
          fontSize={size}
          fontFamily="Inter"
          fontWeight="700"
          fill={color}
          align="center"
          verticalAlign="middle"
        />
      </Group>
    );
  };

  /**
   * Render frame
   */
  const renderFrame = () => {
    if (!decoData.config || !decoData.config.frame) return null;
    const config = decoData.config.frame;
    if (!config.enabled) return null;

    const { style, color } = config;
    const frameColor = color || '#666666';

    // Simple frame rendering based on available config
    if (style === 'minimal') {
      return (
        <Rect
          x={0}
          y={0}
          width={SLIDE_WIDTH}
          height={SLIDE_HEIGHT}
          stroke={frameColor}
          strokeWidth={4}
          opacity={1}
          perfectDrawEnabled={false}
        />
      );
    }

    return null;
  };

/**
    * Render background effects
    */
  const renderBackgroundEffects = () => {
    if (!decoData.config || !decoData.config.backgroundEffects) return null;
    const effects = decoData.config.backgroundEffects;
    if (!effects) return null;

    return (
      <>
        {effects.shadow && (
          <Rect
            x={0}
            y={0}
            width={element.width}
            height={element.height}
            fill="black"
            opacity={0.3}
            offsetX={0}
            offsetY={0}
            blur={10}
          />
        )}
        {effects.glow && (
          <Rect
            x={0}
            y={0}
            width={element.width}
            height={element.height}
            fill="#00E5FF"
            opacity={0.3}
            blur={20}
            globalCompositeOperation="screen"
          />
        )}
        {effects.blur && (
          <Rect
            x={0}
            y={0}
            width={element.width}
            height={element.height}
            fill="transparent"
            opacity={1}
            blur={5}
          />
        )}
        {effects.noise && (
          <Rect
            x={0}
            y={0}
            width={element.width}
            height={element.height}
            fill="white"
            opacity={0.05}
            globalCompositeOperation="overlay"
            perfectDrawEnabled={false}
          />
        )}
      </>
    );
  };

  /**
   * Render decorator based on type
   */
  const renderDecorator = () => {
    try {
      switch (decoData.decoratorType) {
        case 'corner':
          return (
            <Group>
              {renderCornerAccent('topLeft')}
              {renderCornerAccent('topRight')}
              {renderCornerAccent('bottomLeft')}
              {renderCornerAccent('bottomRight')}
            </Group>
          );

        case 'border':
          return renderBorder();

        case 'frame':
          return renderFrame();

        case 'slideNumber':
          return renderSlideNumber();

        case 'logo':
          return renderLogo();

        case 'hashtag':
          return renderHashtag();

        case 'watermark':
          return renderWatermark();

        case 'pillarLabel':
          return renderPillarLabel();

        case 'line':
          return (
            <Group>
              {renderAccentLine('top')}
              {renderAccentLine('bottom')}
              {renderAccentLine('left')}
              {renderAccentLine('right')}
            </Group>
          );

        default:
          console.warn(`[DecoratorElement] Unknown decorator type: ${decoData.decoratorType}`);
          return null;
      }
    } catch (error) {
      console.error('[DecoratorElement] Error rendering decorator:', error);
      return null;
    }
  };

  return (
    <BaseElement
      element={element}
      isSelected={isSelected}
      onSelect={onSelect}
      onTransform={onTransform}
      enableResize={enableResize}
      enableRotate={enableRotate}
      keepAspectRatio={keepAspectRatio}
    >
      <Group>
        {/* Editing visual feedback */}
        {editingGlow}
        {editingPulse}

        {/* Render background effects first */}
        {renderBackgroundEffects()}

        {/* Render decorator */}
        {renderDecorator()}
      </Group>
    </BaseElement>
  );
};