/**
 * Touch Gesture Utilities
 *
 * Provides utilities for handling touch gestures in the canvas editor.
 * Supports drag, resize, rotate, and pinch-to-zoom gestures.
 *
 * @module TouchGestures
 */

import { Point, Transform } from '@/types/canvas-elements';

/**
 * Touch point interface
 */
export interface TouchPoint {
  identifier: number;
  x: number;
  y: number;
  clientX: number;
  clientY: number;
}

/**
 * Touch gesture state
 */
export interface TouchGestureState {
  isActive: boolean;
  touches: Map<number, TouchPoint>;
  startPoint: Point;
  currentPoint: Point;
  timestamp: number;
}

/**
 * Pinch gesture state
 */
export interface PinchGestureState {
  isActive: boolean;
  initialDistance: number;
  currentDistance: number;
  initialCenter: Point;
  currentCenter: Point;
  scale: number;
}

/**
 * Rotation gesture state
 */
export interface RotationGestureState {
  isActive: boolean;
  initialAngle: number;
  currentAngle: number;
  center: Point;
}

/**
 * Touch event types
 */
export type TouchEventType =
  | 'touchstart'
  | 'touchmove'
  | 'touchend'
  | 'touchcancel';

/**
 * Gesture types
 */
export type GestureType =
  | 'tap'
  | 'double-tap'
  | 'long-press'
  | 'drag'
  | 'pinch'
  | 'rotate'
  | 'swipe'
  | 'none';

/**
 * Swipe direction
 */
export type SwipeDirection = 'up' | 'down' | 'left' | 'right' | 'none';

/**
 * Tap event interface
 */
export interface TapEvent {
  type: 'tap';
  point: Point;
  timestamp: number;
}

/**
 * Double tap event interface
 */
export interface DoubleTapEvent {
  type: 'double-tap';
  point: Point;
  firstTapTime: number;
  secondTapTime: number;
}

/**
 * Long press event interface
 */
export interface LongPressEvent {
  type: 'long-press';
  point: Point;
  duration: number;
}

/**
 * Drag event interface
 */
export interface DragEvent {
  type: 'drag';
  startPoint: Point;
  currentPoint: Point;
  delta: Point;
  distance: number;
}

/**
 * Pinch event interface
 */
export interface PinchEvent {
  type: 'pinch';
  center: Point;
  scale: number;
  deltaScale: number;
}

/**
 * Rotate event interface
 */
export interface RotateEvent {
  type: 'rotate';
  center: Point;
  angle: number;
  deltaAngle: number;
}

/**
 * Swipe event interface
 */
export interface SwipeEvent {
  type: 'swipe';
  startPoint: Point;
  endPoint: Point;
  direction: SwipeDirection;
  velocity: number;
}

/**
 * Gesture event union type
 */
export type GestureEvent =
  | TapEvent
  | DoubleTapEvent
  | LongPressEvent
  | DragEvent
  | PinchEvent
  | RotateEvent
  | SwipeEvent;

/**
 * Touch gesture configuration
 */
export interface TouchGestureConfig {
  tapThreshold?: number; // Maximum distance for tap (pixels)
  tapTimeout?: number; // Maximum time for tap (ms)
  doubleTapTimeout?: number; // Maximum time between taps (ms)
  longPressTimeout?: number; // Minimum time for long press (ms)
  swipeThreshold?: number; // Minimum distance for swipe (pixels)
  swipeVelocityThreshold?: number; // Minimum velocity for swipe (pixels/ms)
  pinchThreshold?: number; // Minimum distance for pinch (pixels)
  rotateThreshold?: number; // Minimum angle for rotation (degrees)
  momentumEnabled?: boolean; // Enable momentum scrolling
  momentumDecay?: number; // Momentum decay factor (0-1)
}

/**
 * Default configuration
 */
const DEFAULT_CONFIG: Required<TouchGestureConfig> = {
  tapThreshold: 10,
  tapTimeout: 300,
  doubleTapTimeout: 300,
  longPressTimeout: 500,
  swipeThreshold: 50,
  swipeVelocityThreshold: 0.5,
  pinchThreshold: 20,
  rotateThreshold: 5,
  momentumEnabled: true,
  momentumDecay: 0.95,
};

/**
 * TouchGesture class
 *
 * Handles touch gesture recognition and event generation.
 */
export class TouchGesture {
  private config: Required<TouchGestureConfig>;
  private state: TouchGestureState;
  private pinchState: PinchGestureState;
  private rotateState: RotationGestureState;
  private lastTap: TapEvent | null = null;
  private longPressTimer: number | null = null;
  private gestureType: GestureType = 'none';
  private callbacks: Map<GestureType, (event: GestureEvent) => void>;

  constructor(config: TouchGestureConfig = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.state = this.createInitialState();
    this.pinchState = this.createInitialPinchState();
    this.rotateState = this.createInitialRotateState();
    this.callbacks = new Map();
  }

  /**
   * Create initial touch state
   */
  private createInitialState(): TouchGestureState {
    return {
      isActive: false,
      touches: new Map(),
      startPoint: { x: 0, y: 0 },
      currentPoint: { x: 0, y: 0 },
      timestamp: 0,
    };
  }

  /**
   * Create initial pinch state
   */
  private createInitialPinchState(): PinchGestureState {
    return {
      isActive: false,
      initialDistance: 0,
      currentDistance: 0,
      initialCenter: { x: 0, y: 0 },
      currentCenter: { x: 0, y: 0 },
      scale: 1,
    };
  }

  /**
   * Create initial rotation state
   */
  private createInitialRotateState(): RotationGestureState {
    return {
      isActive: false,
      initialAngle: 0,
      currentAngle: 0,
      center: { x: 0, y: 0 },
    };
  }

  /**
   * Register callback for gesture type
   */
  on(gestureType: GestureType, callback: (event: GestureEvent) => void): void {
    this.callbacks.set(gestureType, callback);
  }

  /**
   * Remove callback for gesture type
   */
  off(gestureType: GestureType): void {
    this.callbacks.delete(gestureType);
  }

  /**
   * Handle touch start
   */
  handleTouchStart(touches: React.TouchList): void {
    const touchArray = Array.from(touches);

    // Update touch state
    touchArray.forEach(touch => {
      this.state.touches.set(touch.identifier, {
        identifier: touch.identifier,
        x: touch.clientX,
        y: touch.clientY,
        clientX: touch.clientX,
        clientY: touch.clientY,
      });
    });

    // Start gesture
    if (touchArray.length === 1) {
      this.state.isActive = true;
      this.state.startPoint = { x: touchArray[0].clientX, y: touchArray[0].clientY };
      this.state.currentPoint = { x: touchArray[0].clientX, y: touchArray[0].clientY };
      this.state.timestamp = Date.now();

      // Start long press timer
      this.longPressTimer = window.setTimeout(() => {
        if (this.state.isActive && this.state.touches.size === 1) {
          this.emitGesture({
            type: 'long-press',
            point: this.state.currentPoint,
            duration: Date.now() - this.state.timestamp,
          });
        }
      }, this.config.longPressTimeout);
    } else if (touchArray.length === 2) {
      // Two-finger gesture
      this.clearLongPressTimer();
      this.state.isActive = false;

      const touch1 = this.state.touches.get(touchArray[0].identifier)!;
      const touch2 = this.state.touches.get(touchArray[1].identifier)!;

      const distance = this.calculateDistance(touch1, touch2);
      const center = this.calculateCenter(touch1, touch2);

      if (distance > this.config.pinchThreshold) {
        // Pinch gesture
        this.pinchState.isActive = true;
        this.pinchState.initialDistance = distance;
        this.pinchState.currentDistance = distance;
        this.pinchState.initialCenter = center;
        this.pinchState.currentCenter = center;
        this.pinchState.scale = 1;
      }

      const angle = this.calculateAngle(touch1, touch2);
      if (Math.abs(angle) > this.config.rotateThreshold) {
        // Rotate gesture
        this.rotateState.isActive = true;
        this.rotateState.initialAngle = angle;
        this.rotateState.currentAngle = angle;
        this.rotateState.center = center;
      }
    }
  }

  /**
   * Handle touch move
   */
  handleTouchMove(touches: React.TouchList): void {
    const touchArray = Array.from(touches);

    // Update touch positions
    touchArray.forEach(touch => {
      const touchPoint = this.state.touches.get(touch.identifier);
      if (touchPoint) {
        touchPoint.x = touch.clientX;
        touchPoint.y = touch.clientY;
        touchPoint.clientX = touch.clientX;
        touchPoint.clientY = touch.clientY;
      }
    });

    if (touchArray.length === 1 && this.state.isActive) {
      // Single finger drag
      const touch = touchArray[0];
      const currentPoint = { x: touch.clientX, y: touch.clientY };
      const delta = {
        x: currentPoint.x - this.state.startPoint.x,
        y: currentPoint.y - this.state.startPoint.y,
      };
      const distance = this.calculateDistance(
        this.state.touches.get(touch.identifier)!,
        { identifier: touch.identifier, x: this.state.startPoint.x, y: this.state.startPoint.y, clientX: this.state.startPoint.x, clientY: this.state.startPoint.y }
      );

      this.state.currentPoint = currentPoint;

      // Determine gesture type based on distance
      if (distance > this.config.tapThreshold) {
        this.clearLongPressTimer();
        this.gestureType = 'drag';

        this.emitGesture({
          type: 'drag',
          startPoint: this.state.startPoint,
          currentPoint,
          delta,
          distance,
        });
      }
    } else if (touchArray.length === 2) {
      // Two-finger gestures
      const touch1 = this.state.touches.get(touchArray[0].identifier)!;
      const touch2 = this.state.touches.get(touchArray[1].identifier)!;

      const distance = this.calculateDistance(touch1, touch2);
      const center = this.calculateCenter(touch1, touch2);

      // Pinch gesture
      if (this.pinchState.isActive) {
        this.pinchState.currentDistance = distance;
        this.pinchState.currentCenter = center;
        this.pinchState.scale = distance / this.pinchState.initialDistance;

        this.emitGesture({
          type: 'pinch',
          center,
          scale: this.pinchState.scale,
          deltaScale: this.pinchState.scale - 1,
        });
      }

      // Rotate gesture
      const angle = this.calculateAngle(touch1, touch2);
      if (this.rotateState.isActive) {
        this.rotateState.currentAngle = angle;

        this.emitGesture({
          type: 'rotate',
          center,
          angle,
          deltaAngle: angle - this.rotateState.initialAngle,
        });
      }
    }
  }

  /**
   * Handle touch end
   */
  handleTouchEnd(touches: React.TouchList): void {
    const touchArray = Array.from(touches);

    // Remove ended touches
    const currentIdentifiers = new Set(touchArray.map(t => t.identifier));
    for (const [identifier, _] of this.state.touches) {
      if (!currentIdentifiers.has(identifier)) {
        this.state.touches.delete(identifier);
      }
    }

    if (touchArray.length === 0) {
      // All touches ended
      this.clearLongPressTimer();

      if (this.state.isActive) {
        // Check for tap
        const distance = this.calculateDistance(
          { identifier: 0, x: this.state.startPoint.x, y: this.state.startPoint.y, clientX: this.state.startPoint.x, clientY: this.state.startPoint.y },
          { identifier: 1, x: this.state.currentPoint.x, y: this.state.currentPoint.y, clientX: this.state.currentPoint.x, clientY: this.state.currentPoint.y }
        );
        const duration = Date.now() - this.state.timestamp;

        if (distance < this.config.tapThreshold && duration < this.config.tapTimeout) {
          const tapEvent: TapEvent = {
            type: 'tap',
            point: this.state.currentPoint,
            timestamp: Date.now(),
          };

          // Check for double tap
          if (this.lastTap) {
            const timeDiff = tapEvent.timestamp - this.lastTap.timestamp;
            const distDiff = this.calculateDistance(
              { identifier: 0, x: this.lastTap.point.x, y: this.lastTap.point.y, clientX: this.lastTap.point.x, clientY: this.lastTap.point.y },
              { identifier: 1, x: tapEvent.point.x, y: tapEvent.point.y, clientX: tapEvent.point.x, clientY: tapEvent.point.y }
            );

            if (timeDiff < this.config.doubleTapTimeout && distDiff < this.config.tapThreshold) {
              this.emitGesture({
                type: 'double-tap',
                point: tapEvent.point,
                firstTapTime: this.lastTap.timestamp,
                secondTapTime: tapEvent.timestamp,
              });
              this.lastTap = null;
            } else {
              this.emitGesture(tapEvent);
              this.lastTap = tapEvent;
            }
          } else {
            this.emitGesture(tapEvent);
            this.lastTap = tapEvent;
          }
        } else if (this.gestureType === 'drag') {
          // Check for swipe
          const duration = Date.now() - this.state.timestamp;
          const delta = {
            x: this.state.currentPoint.x - this.state.startPoint.x,
            y: this.state.currentPoint.y - this.state.startPoint.y,
          };
          const velocity = this.calculateDistance(
            { identifier: 0, x: 0, y: 0, clientX: 0, clientY: 0 },
            { identifier: 1, x: delta.x, y: delta.y, clientX: delta.x, clientY: delta.y }
          ) / duration;

          if (velocity > this.config.swipeVelocityThreshold) {
            this.emitGesture({
              type: 'swipe',
              startPoint: this.state.startPoint,
              endPoint: this.state.currentPoint,
              direction: this.calculateSwipeDirection(delta),
              velocity,
            });
          }
        }
      }

      // Reset states
      this.state = this.createInitialState();
      this.pinchState = this.createInitialPinchState();
      this.rotateState = this.createInitialRotateState();
      this.gestureType = 'none';
    } else if (touchArray.length === 1) {
      // One touch remaining (from two)
      this.pinchState.isActive = false;
      this.rotateState.isActive = false;
    }
  }

  /**
   * Handle touch cancel
   */
  handleTouchCancel(): void {
    this.clearLongPressTimer();
    this.state = this.createInitialState();
    this.pinchState = this.createInitialPinchState();
    this.rotateState = this.createInitialRotateState();
    this.gestureType = 'none';
  }

  /**
   * Clear long press timer
   */
  private clearLongPressTimer(): void {
    if (this.longPressTimer !== null) {
      clearTimeout(this.longPressTimer);
      this.longPressTimer = null;
    }
  }

  /**
   * Calculate distance between two touch points
   */
  private calculateDistance(touch1: TouchPoint, touch2: TouchPoint): number {
    const dx = touch2.x - touch1.x;
    const dy = touch2.y - touch1.y;
    return Math.sqrt(dx * dx + dy * dy);
  }

  /**
   * Calculate center point between two touch points
   */
  private calculateCenter(touch1: TouchPoint, touch2: TouchPoint): Point {
    return {
      x: (touch1.x + touch2.x) / 2,
      y: (touch1.y + touch2.y) / 2,
    };
  }

  /**
   * Calculate angle between two touch points (in degrees)
   */
  private calculateAngle(touch1: TouchPoint, touch2: TouchPoint): number {
    const dx = touch2.x - touch1.x;
    const dy = touch2.y - touch1.y;
    return (Math.atan2(dy, dx) * 180) / Math.PI;
  }

  /**
   * Calculate swipe direction
   */
  private calculateSwipeDirection(delta: Point): SwipeDirection {
    const absX = Math.abs(delta.x);
    const absY = Math.abs(delta.y);

    if (absX > absY) {
      return delta.x > 0 ? 'right' : 'left';
    } else {
      return delta.y > 0 ? 'down' : 'up';
    }
  }

  /**
   * Emit gesture event
   */
  private emitGesture(event: GestureEvent): void {
    const callback = this.callbacks.get(event.type);
    if (callback) {
      callback(event);
    }
  }

  /**
   * Check if gesture is active
   */
  isGestureActive(): boolean {
    return (
      this.state.isActive ||
      this.pinchState.isActive ||
      this.rotateState.isActive
    );
  }

  /**
   * Get current gesture type
   */
  getCurrentGestureType(): GestureType {
    return this.gestureType;
  }

  /**
   * Reset gesture state
   */
  reset(): void {
    this.clearLongPressTimer();
    this.state = this.createInitialState();
    this.pinchState = this.createInitialPinchState();
    this.rotateState = this.createInitialRotateState();
    this.gestureType = 'none';
    this.lastTap = null;
  }
}

/**
 * Convert touch event to point
 */
export function touchToPoint(touch: Touch): Point {
  return {
    x: touch.clientX,
    y: touch.clientY,
  };
}

/**
 * Convert touch event to canvas coordinates
 */
export function touchToCanvas(
  touch: Touch | React.Touch,
  stage: any, // Konva.Stage
): Point {
  const stagePos = stage.position();
  const stageScale = stage.scaleX();
  const touchPoint = {
    x: touch.clientX,
    y: touch.clientY,
  };

  return {
    x: (touchPoint.x - stagePos.x) / stageScale,
    y: (touchPoint.y - stagePos.y) / stageScale,
  };
}

/**
 * Check if touch event is multi-touch
 */
export function isMultiTouch(touches: React.TouchList): boolean {
  return touches.length > 1;
}

/**
 * Get distance between two touches
 */
export function getTouchDistance(touch1: Touch, touch2: Touch): number {
  const dx = touch2.clientX - touch1.clientX;
  const dy = touch2.clientY - touch1.clientY;
  return Math.sqrt(dx * dx + dy * dy);
}

/**
 * Get center point between two touches
 */
export function getTouchCenter(touch1: Touch, touch2: Touch): Point {
  return {
    x: (touch1.clientX + touch2.clientX) / 2,
    y: (touch1.clientY + touch2.clientY) / 2,
  };
}

/**
 * Get angle between two touches (in degrees)
 */
export function getTouchAngle(touch1: Touch, touch2: Touch): number {
  const dx = touch2.clientX - touch1.clientX;
  const dy = touch2.clientY - touch1.clientY;
  return (Math.atan2(dy, dx) * 180) / Math.PI;
}

/**
 * Prevent default touch behavior
 */
export function preventTouchDefault(e: React.TouchEvent): void {
  e.preventDefault();
}

/**
 * Stop touch propagation
 */
export function stopTouchPropagation(e: React.TouchEvent): void {
  e.stopPropagation();
}

/**
 * Check if device supports touch
 */
export function isTouchDevice(): boolean {
  return (
    typeof window !== 'undefined' &&
    ('ontouchstart' in window ||
      navigator.maxTouchPoints > 0 ||
      // @ts-ignore
      navigator.msMaxTouchPoints > 0)
  );
}

/**
 * Get touch support level
 */
export function getTouchSupportLevel(): 'none' | 'basic' | 'multi' {
  if (!isTouchDevice()) return 'none';
  if (navigator.maxTouchPoints > 1) return 'multi';
  return 'basic';
}