import React, { useRef, useEffect, useCallback } from 'react';
import { Group, Transformer } from 'react-konva';
import { useCanvasStore } from '@/store/canvas-store';
import { CanvasElement, Transform } from '@/types/canvas-elements';
import { SLIDE_WIDTH, SLIDE_HEIGHT } from '@/config/constants';
import { useTouchDrag, useTouchResize, useTouchRotate } from '@/canvas-editor/hooks/useTouchGestures';

interface ElementWrapperProps {
  element: CanvasElement;
  isSelected: boolean;
  onSelect: (id: string) => void;
  onTransform: (transform: Transform) => void;
  children: React.ReactNode;
  enableResize?: boolean;
  enableRotate?: boolean;
  keepAspectRatio?: boolean;
}

export const ElementWrapper: React.FC<ElementWrapperProps> = ({
  element,
  isSelected,
  onSelect,
  onTransform,
  children,
  enableResize = true,
  enableRotate = true,
  keepAspectRatio = false,
}) => {
  const shapeRef = useRef<any>(null); // Konva.Node
  const trRef = useRef<any>(null); // Konva.Transformer
  const stageRef = useRef<any>(null); // Konva.Stage (passed from parent)

  // Touch gesture hooks
  const touchDrag = useTouchDrag(
    element,
    () => {
      // Drag start - No action needed
    },
    (transform) => {
      onTransform(transform);
    },
    onTransform, // Phase 3: Pass onTransform for real-time updates
    {
      tapThreshold: 10,
      tapTimeout: 300,
    }
  );

  const touchResize = useTouchResize(
    element,
    'bottom-right', // Default resize handle (can be made configurable)
    () => {
      // Resize start - No action needed
    },
    (transform) => {
      onTransform(transform);
    },
    onTransform, // Phase 3: Pass onTransform for real-time updates
    keepAspectRatio,
    {
      tapThreshold: 10,
      tapTimeout: 300,
    }
  );

  const touchRotate = useTouchRotate(
    element,
    () => {
      // Rotate start - No action needed
    },
    (rotation) => {
      onTransform({ x: element.x, y: element.y, rotation });
    },
    onTransform, // Phase 3: Pass onTransform for real-time updates
    {
      tapThreshold: 10,
      tapTimeout: 300,
    }
  );

  // Attach transformer when element is selected
  useEffect(() => {
    if (isSelected && trRef.current && shapeRef.current) {
      trRef.current.nodes([shapeRef.current]);
      trRef.current.getLayer()?.batchDraw();
    }
  }, [isSelected]);

  // Get stage reference from parent
  useEffect(() => {
    if (shapeRef.current) {
      const stage = shapeRef.current.getStage();
      if (stage) {
        stageRef.current = stage;
      }
    }
  }, []);

  const handleClick = useCallback(
    (e: any) => {
      // Konva events use cancelBubble instead of stopPropagation
      if (e.cancelBubble !== undefined) {
        e.cancelBubble = true;
      }
      // Also try target.stopPropagation() if available
      if (e.target && e.target.stopPropagation) {
        e.target.stopPropagation();
      }
      onSelect(element.id);
    },
    [element.id, onSelect]
  );

  const handleDragEnd = useCallback(
    (e: any) => {
      const node = e.target;
      const transform: Transform = {
        x: node.x(),
        y: node.y(),
      };

      console.log('[ElementWrapper] Drag end for', element.name);
      console.log('[ElementWrapper] New position:', transform.x, transform.y);

      // DISABLED: Constrain to slide bounds - was forcing elements to center
      // The constraint bounds were too restrictive, forcing elements back to
      // the center (540, 675) when dragged outside certain bounds
      // const constrainedTransform = constrainToBounds(transform, node.width(), node.height());
      // node.x(constrainedTransform.x);
      // node.y(constrainedTransform.y);

      console.log('[ElementWrapper] Calling onTransform:', transform);
      onTransform(transform);
    },
    [element.name, onTransform]
  );

  const handleTransformEnd = useCallback(
    (e: any) => {
      const node = e.target;

      // Get current transform
      const scaleX = node.scaleX();
      const scaleY = node.scaleY();

      // Reset scale (we store width/height instead)
      node.scaleX(1);
      node.scaleY(1);

      // Calculate new dimensions
      const newWidth = Math.max(10, node.width() * scaleX);
      const newHeight = Math.max(10, node.height() * scaleY);

      const transform: Transform = {
        x: node.x(),
        y: node.y(),
        width: newWidth,
        height: newHeight,
        rotation: node.rotation(),
      };

      // DISABLED: Constrain to slide bounds - was forcing elements to center
      // const constrainedTransform = constrainToBounds(transform, newWidth, newHeight);
      onTransform(transform);
    },
    [onTransform]
  );

  const constrainToBounds = useCallback(
    (transform: Transform, width: number, height: number): Transform => {
      const halfWidth = width / 2;
      const halfHeight = height / 2;

      return {
        ...transform,
        x: Math.max(halfWidth, Math.min(SLIDE_WIDTH - halfWidth, transform.x)),
        y: Math.max(halfHeight, Math.min(SLIDE_HEIGHT - halfHeight, transform.y)),
      };
    },
    []
  );

  // Touch event handlers
  const handleTouchStart = useCallback(
    (e: any) => {
      // Konva events use cancelBubble instead of stopPropagation
      if (e.cancelBubble !== undefined) {
        e.cancelBubble = true;
      }

      if (!stageRef.current) {
        console.warn('Stage reference not available');
        return;
      }

      if (e.touches.length === 1) {
        // Single touch - drag or select
        if (isSelected) {
          touchDrag.onTouchStart(e, stageRef.current);
        } else {
          onSelect(element.id);
        }
      } else if (e.touches.length === 2) {
        // Two touch - rotate
        if (isSelected && enableRotate) {
          touchRotate.onTouchStart(e, stageRef.current);
        }
      }
    },
    [isSelected, enableRotate, element.id, onSelect, touchDrag, touchRotate]
  );

  const handleTouchMove = useCallback(
    (e: any) => {
      // Konva events use cancelBubble instead of stopPropagation
      if (e.cancelBubble !== undefined) {
        e.cancelBubble = true;
      }

      if (e.touches.length === 1) {
        touchDrag.onTouchMove(e);
      } else if (e.touches.length === 2) {
        touchRotate.onTouchMove(e);
      }
    },
    [touchDrag, touchRotate]
  );

  const handleTouchEnd = useCallback(
    (e: any) => {
      // Konva events use cancelBubble instead of stopPropagation
      if (e.cancelBubble !== undefined) {
        e.cancelBubble = true;
      }

      if (e.touches.length === 0) {
        touchDrag.onTouchEnd(e, stageRef.current);
        touchRotate.onTouchEnd(e);
      }
    },
    [touchDrag, touchRotate]
  );

  // Configure transformer anchors
  const enabledAnchors = enableResize
    ? [
        'top-left',
        'top-center',
        'top-right',
        'middle-left',
        'middle-right',
        'bottom-left',
        'bottom-center',
        'bottom-right',
      ]
    : [];

  return (
    <>
      <Group
        ref={shapeRef}
        id={element.id}
        x={element.x}
        y={element.y}
        width={element.width}
        height={element.height}
        rotation={element.rotation}
        scaleX={element.scaleX}
        scaleY={element.scaleY}
        opacity={element.opacity}
        visible={element.visible}
        draggable={isSelected && !element.locked}
        onClick={handleClick}
        onTap={handleClick}
        onDragEnd={handleDragEnd}
        onTransformEnd={handleTransformEnd}
        // Touch events
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
      >
        {children}
      </Group>

      {isSelected && !element.locked && (
        <Transformer
          ref={trRef}
          enabledAnchors={enabledAnchors}
          rotateEnabled={enableRotate}
          keepRatio={keepAspectRatio}
          boundBoxFunc={(oldBox: any, newBox: any) => {
            // Prevent element from becoming too small
            if (newBox.width < 10 || newBox.height < 10) {
              return oldBox;
            }
            return newBox;
          }}
          // Styling
          anchorSize={10}
          anchorStroke="#00E5FF"
          anchorFill="#00E5FF"
          anchorCornerRadius={2}
          borderStroke="#00E5FF"
          borderStrokeWidth={2}
          borderDash={[4, 4]}
        />
      )}
    </>
  );
};