'use client';

import React, { useRef, useMemo } from 'react';
import { Group, Rect, Text, Circle, Star, Line } from 'react-konva';
import { BaseElement } from './BaseElement';
import { CanvasElement, CTAElementData } from '@/types/canvas-elements';

// Constants
const SLIDE_WIDTH = 1080;
const SLIDE_HEIGHT = 1350;

/**
 * Helper function to darken a hex color by a percentage
 */
function darkenColor(hexColor: string, percent: number): string {
  // Remove hash if present
  const hex = hexColor.replace('#', '');

  // Parse hex values
  const r = parseInt(hex.substring(0, 2), 16);
  const g = parseInt(hex.substring(2, 4), 16);
  const b = parseInt(hex.substring(4, 6), 16);

  // Darken by percentage
  const factor = 1 - percent / 100;
  const newR = Math.round(r * factor);
  const newG = Math.round(g * factor);
  const newB = Math.round(b * factor);

  // Convert back to hex
  return `#${newR.toString(16).padStart(2, '0')}${newG.toString(16).padStart(2, '0')}${newB.toString(16).padStart(2, '0')}`;
}

interface CTAElementProps {
  element: CanvasElement;
  isSelected: boolean;
  onSelect: (id: string) => void;
  onTransform: (transform: any) => void;
  enableResize?: boolean;
  enableRotate?: boolean;
  keepAspectRatio?: boolean;
}

/**
 * CTAElement - Renders CTA buttons in the canvas editor
 *
 * Features:
 * - Button styles: solid, outline, gradient, glowing, minimal
 * - Button shapes: pill, rounded, square, custom
 * - Icons with positions: left, right, center
 * - Animations: pulse, glow, bounce, shake
 * - Custom border radius for custom shapes
 * - Shadow effects
 * - Clickable URLs
 */
export const CTAElement: React.FC<CTAElementProps> = ({
  element,
  isSelected,
  onSelect,
  onTransform,
  enableResize = true,
  enableRotate = true,
  keepAspectRatio = false,
}) => {
  const ctaData = element.data as CTAElementData;
  const [isHovered, setIsHovered] = React.useState(false);

  /**
   * Calculate button dimensions based on shape
   */
  const getButtonDimensions = () => {
    const { width, height } = element;

    switch (ctaData.shape) {
      case 'pill':
        // Pill shape: curved sides
        return {
          width,
          height,
          radius: height / 2,
        };

      case 'rounded':
        // Rounded shape: moderate radius
        return {
          width,
          height,
          radius: ctaData.borderRadius || Math.min(width, height) / 8,
        };

      case 'square':
        // Square shape: no radius or custom
        return {
          width,
          height,
          radius: ctaData.borderRadius || 0,
        };

      case 'custom':
        // Custom radius from data
        return {
          width,
          height,
          radius: ctaData.borderRadius || Math.min(width, height) / 8,
        };

      default:
        // Default to pill
        return {
          width,
          height,
          radius: height / 2,
        };
    }
  };

  /**
   * Get button background color based on style
   */
  const getButtonBackground = () => {
    const { backgroundColor, style, textColor } = ctaData;

    switch (style) {
      case 'solid':
        // Darken on hover
        return isHovered ? darkenColor(backgroundColor, 20) : backgroundColor;

      case 'outline':
        // Show background on hover
        return isHovered ? `${backgroundColor}33` : 'transparent'; // 20% opacity

      case 'gradient':
        // Create gradient from primary to secondary color
        // For gradient style, use secondary color as the gradient end
        return isHovered ? darkenColor(backgroundColor, 10) : backgroundColor;

      case 'glowing':
        // Glowing effect will be handled in effects
        return isHovered ? darkenColor(backgroundColor, 10) : backgroundColor;

      case 'minimal':
        // Show background on hover
        return isHovered ? `${textColor}1A` : 'transparent'; // 10% opacity

      default:
        return backgroundColor;
    }
  };

  /**
   * Get button border color based on style
   */
  const getButtonBorderColor = () => {
    const { backgroundColor, textColor, style } = ctaData;

    switch (style) {
      case 'solid':
        return 'transparent';

      case 'outline':
        return backgroundColor;

      case 'gradient':
        return 'transparent';

      case 'glowing':
        return backgroundColor;

      case 'minimal':
        return textColor;

      default:
        return 'transparent';
    }
  };

  /**
   * Get button text color based on style
   */
  const getButtonTextColor = () => {
    const { textColor, style, backgroundColor } = ctaData;

    switch (style) {
      case 'solid':
        return textColor;

      case 'outline':
        return backgroundColor;

      case 'gradient':
        return textColor;

      case 'glowing':
        return textColor;

      case 'minimal':
        return backgroundColor;

      default:
        return textColor;
    }
  };

  /**
   * Get button shadow configuration
   */
  const getButtonShadow = () => {
    const { style, shadow, backgroundColor } = ctaData;

    // Only shadows for solid, gradient, glowing styles
    switch (style) {
      case 'solid':
        if (shadow) {
          return {
            color: 'rgba(0, 0, 0, 0.2)',
            blur: 10,
            offsetX: 0,
            offsetY: 4,
          };
        }
        return undefined;

      case 'gradient':
        if (shadow) {
          return {
            color: 'rgba(0, 0, 0, 0.15)',
            blur: 20,
            offsetX: 0,
            offsetY: 8,
          };
        }
        return undefined;

      case 'glowing':
        // Glowing effect is handled separately
        return undefined;

      case 'minimal':
        return undefined;

      default:
        return undefined;
    }
  };

  /**
   * Get glow effect (for glowing style)
   */
  const getGlowEffect = () => {
    const { style, textColor } = ctaData;
    const pillarColor = textColor;

    switch (style) {
      case 'glowing':
        return {
          color: pillarColor,
          blur: 20,
          offsetX: 0,
          offsetY: 0,
          opacity: 0.6,
        };

      case 'gradient':
        // Gradient has subtle glow too
        return {
          color: pillarColor,
          blur: 15,
          offsetX: 0,
          offsetY: 0,
          opacity: 0.3,
        };

      default:
        return undefined;
    }
  };

  /**
   * Get animation configuration
   */
  const getAnimationConfig = () => {
    const { animation } = ctaData;

    switch (animation) {
      case 'pulse':
        return {
          keyframes: 'pulse',
          duration: 1.5,
          timing: 'ease-in-out',
          iterationCount: 'infinite',
          direction: 'alternate',
        };

      case 'glow':
        return {
          keyframes: 'glow',
          duration: 2,
          timing: 'ease-in-out',
          iterationCount: 'infinite',
          direction: 'alternate',
        };

      case 'bounce':
        return {
          keyframes: 'bounce',
          duration: 1,
          timing: 'ease-in-out',
          iterationCount: 'infinite',
          direction: 'alternate',
        };

      case 'shake':
        return {
          keyframes: 'shake',
          duration: 0.5,
          timing: 'ease-in-out',
          iterationCount: 'infinite',
          direction: 'alternate',
        };

      case 'none':
        return undefined;

      default:
        return undefined;
    }
  };

  /**
   * Get icon position coordinates
   */
  const getIconPosition = () => {
    const { iconPosition } = ctaData;
    const iconSize = 24; // Default icon size

    switch (iconPosition) {
      case 'left':
        return {
          x: -element.width / 2 + 24,
          y: 0,
        };

      case 'right':
        return {
          x: element.width / 2 - 24,
          y: 0,
        };

      case 'center':
        return {
          x: 0,
          y: 0,
        };

      default:
        return {
          x: 0,
          y: 0,
        };
    }
  };

  /**
   * Render button background
   */
  const renderButtonBackground = () => {
    const { style, backgroundColor } = ctaData;
    const { radius } = getButtonDimensions();
    const bgColor = getButtonBackground();
    const borderColor = getButtonBorderColor();

    switch (style) {
      case 'solid':
        return (
          <Rect
            x={-element.width / 2}
            y={-element.height / 2}
            width={element.width}
            height={element.height}
            fill={bgColor}
            cornerRadius={radius}
            shadow={getButtonShadow()}
          />
        );

      case 'gradient':
        return (
          <Rect
            x={-element.width / 2}
            y={-element.height / 2}
            width={element.width}
            height={element.height}
            fill={bgColor}
            cornerRadius={radius}
            shadow={getButtonShadow()}
          />
        );

      case 'outline':
        return (
          <Rect
            x={-element.width / 2}
            y={-element.height / 2}
            width={element.width}
            height={element.height}
            fill="transparent"
            stroke={borderColor}
            strokeWidth={3}
            cornerRadius={radius}
          />
        );

      case 'glowing':
        return (
          <>
            <Rect
              x={-element.width / 2}
              y={-element.height / 2}
              width={element.width}
              height={element.height}
              fill={bgColor}
              cornerRadius={radius}
              shadow={getButtonShadow()}
            />
            <Rect
              x={-element.width / 2}
              y={-element.height / 2}
              width={element.width}
              height={element.height}
              fill="transparent"
              cornerRadius={radius}
              shadow={getGlowEffect()}
            />
          </>
        );

      case 'minimal':
        return (
          <Rect
            x={-element.width / 2}
            y={-element.height / 2}
            width={element.width}
            height={element.height}
            fill="transparent"
            stroke={borderColor}
            strokeWidth={2}
            cornerRadius={radius}
          />
        );

      default:
        return (
          <Rect
            x={-element.width / 2}
            y={-element.height / 2}
            width={element.width}
            height={element.height}
            fill={bgColor}
            cornerRadius={radius}
          />
        );
    }
  };

  /**
   * Render button text and icon
   */
  const renderButtonContent = () => {
    const { text, textColor, icon, iconPosition } = ctaData;
    const iconSize = 24; // Default icon size
    const iconPos = getIconPosition();

    return (
      <Group>
        {/* Icon */}
        {icon && (
          <Text
            x={iconPos.x}
            y={iconPos.y}
            text={icon}
            fontSize={iconSize}
            fontFamily="Arial"
            fill={textColor}
            align="center"
            verticalAlign="middle"
            offsetX={iconPos.x}
            offsetY={iconPos.y}
            fontStyle="bold"
          />
        )}

        {/* Text */}
        {text && (
          <Text
            x={icon ? (iconPosition === 'center' ? 4 : 0) : 0}
            y={0}
            text={text}
            fontSize={Math.min(element.width / 10, 32)}
            fontFamily="Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif"
            fontWeight="600"
            fill={textColor}
            align={iconPosition === 'center' ? 'center' : 'left'}
            verticalAlign="middle"
            offsetY={1}
            fontStyle="bold"
          />
        )}
      </Group>
    );
  };

  /**
   * Render glow animation keyframes
   */
  const renderGlowAnimation = () => {
    return (
      <>
        <style>{`
          @keyframes glow {
            0%, 100% {
              opacity: 0.3;
            }
            50% {
              opacity: 0.8;
            }
          }
        `}</style>
      </>
    );
  };

  /**
   * Render pulse animation keyframes
   */
  const renderPulseAnimation = () => {
    return (
      <>
        <style>{`
          @keyframes pulse {
            0%, 100% {
              opacity: 1;
            }
            50% {
              opacity: 0.8;
            }
          }
        `}</style>
      </>
    );
  };

  /**
   * Render bounce animation keyframes
   */
  const renderBounceAnimation = () => {
    return (
      <>
        <style>{`
          @keyframes bounce {
            0%, 100% {
              transform: translateY(0);
            }
            25% {
              transform: translateY(-10px);
            }
            50% {
              transform: translateY(0);
            }
            75% {
              transform: translateY(-5px);
            }
          }
        `}</style>
      </>
    );
  };

  /**
   * Render shake animation keyframes
   */
  const renderShakeAnimation = () => {
    return (
      <>
        <style>{`
          @keyframes shake {
            0%, 100% {
              transform: translateX(0);
            }
            10%, 30%, 50%, 70%, 90% {
              transform: translateX(-4px);
            }
            20%, 40%, 60%, 80% {
              transform: translateX(4px);
            }
          }
        `}</style>
      </>
    );
  };

  /**
   * Render animation keyframes based on style
   */
  const renderAnimationKeyframes = () => {
    const { animation } = ctaData;

    switch (animation) {
      case 'pulse':
        return renderPulseAnimation();

      case 'glow':
        return renderGlowAnimation();

      case 'bounce':
        return renderBounceAnimation();

      case 'shake':
        return renderShakeAnimation();

      default:
        return null;
    }
  };

  /**
   * Render CTA button
   */
  return (
    <BaseElement
      element={element}
      isSelected={isSelected}
      onSelect={onSelect}
      onTransform={onTransform}
      enableResize={enableResize}
      enableRotate={enableRotate}
      keepAspectRatio={keepAspectRatio}
    >
      <Group
        x={element.x}
        y={element.y}
        width={element.width}
        height={element.height}
        rotation={element.rotation}
        scaleX={element.scaleX}
        scaleY={element.scaleY}
        opacity={element.opacity}
        visible={element.visible}
        draggable={isSelected && !element.locked}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        onClick={(e) => {
          e.cancelBubble = true;
          onSelect(element.id);
          // Handle CTA click if URL is set
          if (ctaData.url) {
            window.open(ctaData.url, '_blank');
          }
        }}
        onTap={(e) => {
          e.cancelBubble = true;
          onSelect(element.id);
          // Handle CTA tap if URL is set
          if (ctaData.url) {
            window.open(ctaData.url, '_blank');
          }
        }}
      >
        {/* Render animation keyframes */}
        {renderAnimationKeyframes()}

        {/* Render button background */}
        {renderButtonBackground()}

        {/* Render button content */}
        {renderButtonContent()}
      </Group>
    </BaseElement>
  );
};