import React from 'react';
import { ElementWrapper } from '../core/ElementWrapper';
import { CanvasElement } from '@/types/canvas-elements';

interface BaseElementProps {
  element: CanvasElement;
  isSelected: boolean;
  onSelect: (id: string) => void;
  onTransform: (transform: any) => void;
  children: React.ReactNode;
  enableResize?: boolean;
  enableRotate?: boolean;
  keepAspectRatio?: boolean;
}

/**
 * Base element component that wraps all canvas elements
 * with common functionality like selection and transformation
 */
export const BaseElement: React.FC<BaseElementProps> = ({
  element,
  isSelected,
  onSelect,
  onTransform,
  children,
  enableResize = true,
  enableRotate = true,
  keepAspectRatio = false,
}) => {
  return (
    <ElementWrapper
      element={element}
      isSelected={isSelected}
      onSelect={onSelect}
      onTransform={onTransform}
      enableResize={enableResize}
      enableRotate={enableRotate}
      keepAspectRatio={keepAspectRatio}
    >
      {children}
    </ElementWrapper>
  );
};